script:
card({ name: "Tic-tac-toe", icon: 'game', permissions: ['sound'] });
const words = {
  start: "Tap a square to start",
  yourTurn: "Your turn",
  waiting: "Waiting for {p0}",
  someone: "the other player",
  youWon: "You won!",
  won: "{p0} won",
  draw: "It's a draw",
  again: "New game",
  over: "The game is over",
  full: "Two people are already playing",
  notYours: "Not your turn",
  taken: "That square is taken",
};

// Two players. The first to tap is X, the next person is O.
const lines = [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];

function init() {
  return { board: Array(9).fill(''), x: null, o: null, names: {}, turn: 'x', winner: null };
}

on.play = (s, args, ctx) => {
  if (s.winner) throw words.over;
  if (!s.x) s.x = ctx.author;
  else if (!s.o && ctx.author !== s.x) s.o = ctx.author;
  const mark = ctx.author === s.x ? 'x' : ctx.author === s.o ? 'o' : null;
  if (!mark) throw words.full;
  if (mark !== s.turn) throw words.notYours;
  if (s.board[args.cell]) throw words.taken;
  s.names[ctx.author] = ctx.authorName;
  s.board[args.cell] = mark;
  for (const [a, b, c] of lines) {
    if (s.board[a] && s.board[a] === s.board[b] && s.board[b] === s.board[c]) s.winner = ctx.author;
  }
  if (!s.winner && s.board.every(m => m)) s.winner = 'draw';
  ctx.sound(s.winner && s.winner !== 'draw' ? 'win' : 'tap');
  s.turn = mark === 'x' ? 'o' : 'x';
};

on.reset = (s) => init();

function view(s, me) {
  const next = s.turn === 'x' ? s.x : s.o;
  let status;
  if (s.winner === 'draw') status = words.draw;
  else if (s.winner) status = s.winner === me.id ? words.youWon : words.won.replace('{p0}', s.names[s.winner]);
  else if (!s.x) status = words.start;
  else if (next === me.id || (!next && me.id !== s.x)) status = words.yourTurn;
  else status = words.waiting.replace('{p0}', s.names[next] || words.someone);
  const marks = { x: 'X', o: 'O', '': '' };
  return column([
    text(status, { bold: true, align: 'center', tone: s.winner === me.id ? 'success' : undefined }),
    grid(3, s.board.map((m, i) => button(marks[m], 'play', { cell: i }, { tone: m === 'x' ? 'accent' : m === 'o' ? 'warning' : undefined }))),
    s.winner ? button(words.again, 'reset', null, { tone: 'accent', align: 'center' }) : spacer(0),
  ]);
}
